1583:  /// Hub mail → real steering messages. The package drain closure already
1584:  /// swallows transport errors (empty list); the guard here only covers
1585:  /// mapping surprises, keeping the never-throw steering contract.
1586:  Future<List<AgentMessage>> _drainHubMail() async {
1587:    try {
1588:      // Session-scope replay lands here (the session JSONL is loaded after
1589:      // registration): the first drain joins what boot could not see (AC3).
1590:      await _syncRuntimeMemberships();
1591:      final repository = _activeRepository;
1592:      final selfId = repository?.client.agentId;
1593:      final hubUrl = _connectedHubUrl;
1594:      final inbound = await _inboundHubMail(repository, selfId);
1595:      final accepted = await _filterHubMail(inbound, selfId, hubUrl);
1596:      return _mapHubMail(accepted);
1597:    } on Object {
1598:      return const [];
1599:    }
1600:  }
