1602:  Future<List<hub.AgentMessage>> _inboundHubMail(
1603:    hub.HubMessagingRepository? repository,
1604:    String? selfId,
1605:  ) async {
1606:    if (repository == null) return _hub.externalSteeringSource();
1607:    return [
1608:      ...await repository.drain(selfId ?? ''),
1609:      for (final channel in await joinedChannelsFor(_hub))
1610:        ...await repository.drain('#$channel'),
1611:    ];
