1614:  Future<List<hub.AgentMessage>> _filterHubMail(
1615:    List<hub.AgentMessage> inbound,
1616:    String? selfId,
1617:    String? hubUrl,
1618:  ) async {
1619:    final accepted = <hub.AgentMessage>[];
1620:    for (final message in inbound) {
1621:      if (await _acceptHubMail(message, selfId, hubUrl)) {
1622:        accepted.add(message);
1623:      }
1624:    }
1625:    return accepted;
