1641:  Future<bool> _acceptsRemoteHubMail(
1642:    hub.AgentMessage message,
1643:    String? hubUrl,
1644:  ) async {
1645:    // Live LEAVE filter (AC4): leaving every scope stops delivery at once;
1646:    // leaving one scope keeps the others. Non-channel mail always passes.
1647:    final scoped = _scoped;
1648:    if (scoped == null || !message.toId.startsWith('#')) return true;
1649:    return scoped.acceptsChannel(
1650:      hubUrl ?? scoped.defaultHubUrl,
1651:      message.toId.substring(1),
1652:    );
1653:  }
