1940:  String _resolvePeerName(String to, List<hub.AgentInfo> peers) {
1941:    final byName = peers.where((peer) => peer.name == to).toList();
1942:    if (byName.length == 1) return byName.single.agentId;
1943:    throw _peerResolutionError(to, peers, byName);
