Future<void> main(List<String> args) async {
  // Provider forensics composition root (gh-1395 review round 1): the
  // pure barrel carries only the contracts; the io seams (env knob
  // lookup, [conn-trace] stderr lines, the observed dart:io client, the
  // sentinel's disk sink) install here — the ONE dart:io boundary.
  installProviderStallForensics();
  // StreamTrace (diagnostic): FA_STREAM_TRACE=1 arms the per-chunk
  // net→emit→render timing trail at ~/.fah/logs/stream-trace.log — the
  // "streamed x ms, rendered y ms" post-mortem for bursty endpoints.
  // HOME everywhere except Windows (USERPROFILE there) — same fallback
  // as _homeDir().
  final homeDir =
      Platform.environment['HOME'] ?? Platform.environment['USERPROFILE'];
  if (homeDir != null && homeDir.isNotEmpty) {
    maybeStartStreamTrace(
      File('$homeDir/.fah/logs/stream-trace.log'),
      envLookup: (key) => Platform.environment[key],
    );
  }
  // Session segment rotation warnings (fa gh-1077): the session layer has
  // no console dependency — the CLI surfaces hard-cap truncations and
  // rotation fallbacks on stderr.
  JsonlSessionStorage.onRotationWarning = stderr.writeln;
  await runZoned(
    () => _runApp(args),
    zoneSpecification: ZoneSpecification(
      handleUncaughtError: (self, parent, zone, error, stackTrace) {
        // fa_hub_client can fail a LEAKED waiter (no listener left) with
        // StateError('connection closed') when the socket drops — e.g. a
        // flush() waiter abandoned after _send threw on a dead socket.
        // The error lands here as an unhandled async error no call-site
        // try/catch can reach; the fabric already fell back to files, so
        // log it and keep running instead of crashing the CLI.
        if (isHubConnectionTeardown(error)) {
          stderr.writeln(
            'fa: hub connection closed mid-operation — '
            'continuing on the file fabric',
          );
          return;
        }
        _handleUncaughtError(error, stackTrace);
      },
    ),
  );
}

String _resolveApiKey(
  String provider,
  SecureKeyCache keys, {
  String? fallback,
  String? baseUrl,
  Iterable<String>? scopedKeyNames,
}) {
  final key =
      optionalProviderApiKey(
        provider,
        keys,
        baseUrl: baseUrl,
        scopedKeyNames: scopedKeyNames,
      ) ??
      fallback;
  if (key == null || key.isEmpty) {
    _fail(
      'missing API key: set ${apiKeyEnvNames(provider).first} in the '
      'environment',
    );
  }
  return key;
}

String _defaultSessionRoot() {
  final home = _homeDir();
  if (Platform.isMacOS) {
    // Share sessions with the app only when macOS materialized its App
    // Group container (i.e. the entitled app is installed). Probing must
    // NOT create the container ourselves: under a fake HOME (integration
    // tests) that would silently relocate the sessions they then read.
    final container = '$home/Library/Group Containers/group.dev.fa1.shared';
    final groupDir = '$container/fa/sessions';
    if (Directory(container).existsSync() && _isDirWritable(groupDir)) {
      return groupDir;
    }
    return '$home/.fah/sessions';
  }
  return '$home/.fah/sessions';
}

bool _isDirWritable(String path) {
  try {
    final dir = Directory(path);
    if (!dir.existsSync()) {
      dir.createSync(recursive: true);
    }
    final probe = File('$path/.probe_${DateTime.now().microsecondsSinceEpoch}');
    probe.writeAsStringSync('');
    probe.deleteSync();
    return true;
  } catch (_) {
    return false;
  }
}

String _homeDir() {
  final home =
      Platform.environment['HOME'] ?? Platform.environment['USERPROFILE'];
  if (home == null || home.isEmpty) {
    _fail('cannot resolve home directory; pass --session-root');
  }
  return home;
}

/// This host's machine name for `name@machine` addressing (issue #27
/// phase 2). Null when the platform cannot name the host — suffixed
/// addresses then never resolve locally.
String? _localMachineName() {
  try {
    final name = Platform.localHostname.trim();
    return name.isEmpty ? null : name;
  } on Object {
    return null;
  }
}

/// The runtime `FA_PROVIDERS` env override, applied at startup (the
/// dart-define always wins over it; see [providerEnabledInBuild]).
void _applyProviderFilterEnv() {
  final value = Platform.environment['FA_PROVIDERS'];
  if (value != null && value.trim().isNotEmpty) {
    providerFilterEnvOverride = value;
  }
}

/// Truthy env-var check (`1`/`true`/`yes`/`on`, case-insensitive).
/// The inverse default for flags that are ON unless explicitly disabled:
/// unset or a truthy value → true; only `0`/`false`/`no`/`off` → false.
bool _envNotFalsy(String name) {
  final value = Platform.environment[name]?.trim().toLowerCase();
  return value != '0' && value != 'false' && value != 'no' && value != 'off';
}

/// Truthy env-var check for opt-in flags (`1`/`true`/`yes`/`on`).
bool _envTruthy(String name) {
  final value = Platform.environment[name]?.trim().toLowerCase();
  return value == '1' || value == 'true' || value == 'yes' || value == 'on';
}

/// Tri-state env-var check: `1/true/yes/on` → true, `0/false/no/off` →
/// false, unset or unrecognized (e.g. `auto`) → null. Strict sets — any
/// other garbage must not silently force the flag on.
bool? _envTristate(String name) {
  final raw = Platform.environment[name]?.trim().toLowerCase();
  if (raw == null || raw.isEmpty) return null;
  const on = {'1', 'true', 'yes', 'on'};
  const off = {'0', 'false', 'no', 'off'};
  if (on.contains(raw)) return true;
  if (off.contains(raw)) return false;
  return null;
}

/// The executable used to wake asleep cross-session mailboxes: this
/// process's own path when it is a compiled snapshot, or null to fall back
/// to `fa` on PATH (a `dart run` VM cannot be re-spawned with session
/// args).
String? wakeExecutable() {
  final exe = Platform.script.toFilePath();
  final base = exe.split(Platform.pathSeparator).last.toLowerCase();
  if (base == 'dart' || base == 'dart.exe') return null;
  return exe;
}

part of 'fah.dart';

Future<void> _runApp(List<String> args) async {
  final packageVersion = _packageVersion();
  // The Copilot PAT-mode user-agent carries the real fa version + OS
  // (`copilot/<version> (<os>) term/unknown`) — lib/ stays pure Dart, so
  // the host installs the identity at startup.
  installCopilotCliIdentity(
    version: packageVersion,
    os: Platform.operatingSystem,
  );
  _applyProviderFilterEnv();
  // Platform-aware chord display (issue #809): Option/Cmd labels on macOS.
  tuiKeyHintDarwin = Platform.isMacOS;
  // `fa serve [--a2a|--bridge] [--port N] [--token T]` — the parser does
  // not know the serve forms, so they are intercepted before CliArgs
  // parsing: serve-specific flags are stripped from the parsed args and
  // kept for the late interception below (after model/key resolution).
  final serve = splitServeA2aArgs(args);
  // `fa wire-serve [--port N] [--stdio] [--token T]` (issue #1103) — the
  // headless AWP server. Intercepted like serve: the parser does not know
  // the form, and the words must never reach prompt parsing. Flag errors
  // (--stdio with --port, a bad --port) are LOUD startup failures (E2) —
  // never a silent fallback to another mode.
  final WireServeArgs wireServe;
  try {
    wireServe = splitWireServeArgs(args);
  } on FormatException catch (error) {
    _fail(
      'usage: fa wire-serve [--port N] [--stdio] [--token T]\n'
      '${error.message}',
    );
  }
  // `fa hub serve [--port N]` — a local DAP hub, no agent boot
  // (docs/dap.md §8.1). Intercepted on the raw args BEFORE the serve
  // marker check below (`hub serve` contains the word "serve" but is a
  // different command): the words must never reach prompt parsing.
  if (args.isNotEmpty && args.first == 'hub') {
    exit(await runHubCommand(args.sublist(1)));
  }
  // `fa dap start|stop|status [--port N]` — the one-step local DAP hub
  // (issue #304): probe/spawn/enroll/stop with no agent boot, same raw-
  // args interception as `fa hub serve`.
  if (args.isNotEmpty && args.first == 'dap') {
    exit(await runDapCommand(args.sublist(1)));
  }
  final serveMarkerCount =
      (serve.serveA2a ? 1 : 0) + (serve.serveBridge ? 1 : 0);
  if (serveMarkerCount != 1 && args.contains('serve')) {
    _fail(
      'usage: fa serve --a2a [--port N] [--token T] | '
      'fa serve --bridge [--port N] [--token T]',
    );
  }

  late final CliArgs parsed;
  try {
    parsed = switch (parseCliArgs(
      wireServe.wireServe ? wireServe.cliArgs : serve.cliArgs,
    )) {
      CliArgsHelp() => _exitWithUsage(packageVersion),
      CliArgsVersion(:final output) => _exitWithVersion(
        packageVersion,
        output: output,
      ),
      final CliArgs cliArgs => cliArgs,
    };
  } on CliArgsException catch (error) {
    stderr.writeln('fa: ${error.message}');
    stderr.writeln('Run with --help for usage.');
    // GOAL exit table (issue #1562): `fa import` usage errors exit 1, not
    // the EX_USAGE 64 the rest of the CLI uses.
    exit(args.isNotEmpty && args.first == 'import' ? 1 : 64);
  }

  // gh-1556: the ONE session deadline clock. The host env seeds it
  // (missing/invalid = feature off, silent); `--timer`/`--deadline`
  // override the env (later wins); `/timer` adjusts it live. An invalid
  // FLAG spec is the user's own words — a usage error, never a silently
  // wrong clock.
  final SessionDeadline sessionDeadline;
  try {
    sessionDeadline = resolveSessionDeadline(
      envValue: Platform.environment[deadlineEpochMsEnvVar],
      flagSpec: parsed.timer ?? parsed.deadline,
    );
  } on FormatException catch (error) {
    // Not dead code: parseCliArgs's `_validateDeadlineFlag` only checks
    // the spec's SHAPE — a well-formed but PAST epoch (e.g.
    // `--deadline 1893456000000`) passes there and throws here, at
    // `SessionDeadline.setEpochMs`. Keep this catch; it defends that one
    // narrow path.
    _fail('invalid --timer/--deadline: ${error.message}');
  }

  // Quick self-management commands, intercepted before prompt resolution:
  // `fa update` swaps in the latest release binary; `fa uninstall` removes
  // the binary + PATH entry (and ~/.fah on a second confirmation).
  if (parsed.positionals.length == 1 && parsed.prompt == null) {
    switch (parsed.positionals.single) {
      case 'update':
        exit(await runSelfUpdate(currentVersion: packageVersion));
      case 'uninstall':
        exit(await runSelfUninstall());
    }
  }
  // `fa trajectory <verb> [sessionId] [--json] [--at N]` — read-only
  // trajectory views over a stored session; intercepted before prompt
  // resolution so the verb words never become a prompt.
  final trajectory = parsed.trajectory;
  if (trajectory != null) {
    exit(await _runTrajectoryCommand(trajectory, parsed));
  }

  // `fa import --harness=... --all|--session=x` — cross-harness session
  // import (issue #1562), intercepted like trajectory: no agent boot and
  // ZERO provider/model/key wiring — imported content can never trigger a
  // model call during import (GOAL F8).
  final importCommand = parsed.importCmd;
  if (importCommand != null) {
    exit(await _runImportCommand(importCommand, parsed));
  }

  // `fa ext <verb> ...` — headless JS extension management, intercepted
  // like trajectory: no agent boot, the exit code propagates.
  final ext = parsed.ext;
  if (ext != null) {
    final extEnv = LocalExecutionEnv(cwd: parsed.cwd ?? Directory.current.path);
    exit(
      await runExtCliCommand(
        ext,
        io: _TerminalCliIO(headless: true),
        env: extEnv,
        projectDir: extEnv.cwd,
        userDir: _homeDir(),
      ),
    );
  }

  // `fa jsr widget:test|widget:screenshot …` — the js_widget_runtime agent
  // CLI pass-through (gh-1033), intercepted like trajectory: no agent
  // boot. The child's stdout/stderr stream straight through and its exit
  // code propagates (CI-usable); platform bits (PATH) come from the
  // process, the only dart:io layer here.
  final jsr = parsed.jsr;
  if (jsr != null) {
    final jsrEnv = LocalExecutionEnv(cwd: parsed.cwd ?? Directory.current.path);
    exit(
      await runJsrCliCommand(
        jsr,
        io: SinkJsrCliIo(
          onStdout: stdout.write,
          onStderr: stderr.write,
          onNote: stderr.writeln,
        ),
        env: jsrEnv,
        projectDir: jsrEnv.cwd,
        pathEnv: Platform.environment['PATH'] ?? '',
        pathListSeparator: Platform.isWindows ? ';' : ':',
        windowsQuoting: Platform.isWindows,
      ),
    );
  }
  // `fa session list [--json] [--flat]` (issue #198) — the tree-grouped
  // session listing, intercepted like trajectory: no agent boot.
  // `fa session repair <sessionId|path> [--dry-run]` (gh-1073) — ledger
  // surgery on a bloated session file, also without booting the agent.
  final sessionList = parsed.sessionList;
  if (sessionList != null) {
    final io = _TerminalCliIO(headless: true);
    final listEnv = LocalExecutionEnv(
      cwd: parsed.cwd ?? Directory.current.path,
    );
    final sessionRoot = parsed.sessionRoot ?? _defaultSessionRoot();
    // One presence store shared by the repair and clean verbs (gh-1746
    // review: the wiring must not drift between the branches).
    final sessionPresenceStore = FileSessionPresenceStore(
      env: listEnv,
      root: sessionRoot,
      // gh-1660: the sweep deletes a stale presence file only when the
      // pid probe pronounces its process dead (or past the cleanup grace
      // without a pid) — wire the POSIX probe so live-but-stale rows are
      // never swept under a listing run.
      pidAlive: probePidAlive,
    );
    // The user's `sessions.retention` policy (gh-1746), read once for
    // both verbs: the clean verb enforces it, the list verb prints the
    // usage footer under a cap (Visibility; REG-1: absent = no footer).
    SessionRetentionConfig readRetention() {
      final cleanHome = homeDirectory();
      if (cleanHome == null || cleanHome.isEmpty) {
        return const SessionRetentionConfig();
      }
      try {
        return loadCliConfig(cleanHome).sessions?.retention ??
            const SessionRetentionConfig();
      } on ConfigException catch (error) {
        _fail('invalid ~/.fah/config.yaml: ${error.message}');
      }
    }

    if (sessionList.verb == 'repair') {
      exit(
        await runSessionRepairCliCommand(
          write: io.write,
          writeln: io.writeln,
          env: listEnv,
          sessionRoot: sessionRoot,
          sessionId: sessionList.repairTarget,
          dryRun: sessionList.dryRun,
          presenceStore: sessionPresenceStore,
        ),
      );
    }
    if (sessionList.verb == 'info') {
      // issue #1882 AC5: the size/records breakdown over one streaming
      // pass. Progress rides stderr; SIGINT cancels into a partial
      // report (exit 130) instead of a silent hang.
      exit(
        await _runSessionInfoVerb(
          io: io,
          env: listEnv,
          sessionRoot: sessionRoot,
          command: sessionList,
        ),
      );
    }
    if (sessionList.verb == 'clean') {
      // gh-1746 AC6: `fa session clean [--dry-run]` — one retention sweep
      // pass, intercepted like repair: no agent boot. The policy comes
      // from the user config (`sessions.retention`, tolerant parse).
      // Reuses the enclosing io/env/root + the shared presence store so
      // the verbs cannot drift (gh-1746 review).
      exit(
        await runSessionCleanCliCommand(
          write: io.write,
          writeln: io.writeln,
          env: listEnv,
          sessionRoot: sessionRoot,
          retention: readRetention(),
          dryRun: sessionList.dryRun,
          presenceStore: sessionPresenceStore,
        ),
      );
    }
