        trajectoryRequestBlobs: trajectoryRequestBlobs,
        trajectoryRequestBlobMaxMb: trajectoryRequestBlobMaxMb,
        trajectoryRequestBlobMaxBytes: trajectoryRequestBlobMaxBytes,
        trajectoryRequestBlobTtlDays: trajectoryRequestBlobTtlDays,
        contextWindowCap: saved.contextWindowCap,
        stuckTool: saved.stuckTool,
        foregroundCall: saved.foregroundCall,
        subagents: saved.subagents,
        jobs: saved.jobs,
        headless: saved.headless,
        // The gh-1198 thinking stream: the `--stream-thinking` flag wins
        // over the `output.streamThinking` config for this run.
        streamThinking: resolveStreamThinking(
          flag: parsed.streamThinking,
          configValue: saved.streamThinking,
        ),
        // The gh-1433 thinking-scoped silence hatch (the parser rejects it
        // together with --stream-thinking).
        noStreamThinking: parsed.noStreamThinking,
        modelRolesResolver: rolesResolver,
        providersQueueRuntime: queueRuntime,
        // The live models config (`models:` section): `/models set`/`remove`
        // mutate its media slot overrides and `/model <name>` resolves its
        // custom model definitions — persisted via persistConfig. An absent
        // section starts as an empty config so the commands always work.
        modelsConfig: saved.models ?? ModelsConfig(),
        onModelsConfigChanged: () async => persistConfig(),
        homeDir: home,
        tuiTheme: saved.tuiTheme,
        // TTSR stream rules: user config (~/.fah/config.yaml `ttsr:`) merged
        // with project rules (.fah/rules.yaml), project first.
        ttsr: _resolveTtsr(saved, cwd),
        // Project-level .fah/config.yaml memory: wins over the user one.
        memoryConfig: loadProjectMemoryConfig(cwd) ?? saved.memory,
        // The saved cube default (the `cube:` section): the settings-hub
        // Cube sandbox flow rewrites it — persisted via persistConfig.
        cubeSettings: saved.cube,
        onCubeSettingsChanged: () async => persistConfig(),
        // DAP / Hub settings flow: the snapshot seam resolves the effective
        // config (env > `hub:` section > `~/.dap/config.json` > defaults)
        // through the hub client and overlays the live plugin status — local
        // reads only, never a network dial. A missing/failed probe keeps the
        // flow honest about the state.
        dapHubState: () async {
          // Single parse source: the same loaded packages.yaml map the
          // plugin system consumes (loadPackagesConfig already flattened
          // the yaml tree to plain Dart values).
          final hubSection = resolved.config['hub'];
          final settings = resolveDapSettings(
            config: HubConfig.fromMap(
              hubSection is Map<String, dynamic> ? hubSection : const {},
              Platform.environment,
            ),
            environment: Platform.environment,
          );
          try {
            final status = await hubPlugin.status();
            return DapHubSnapshot(
              supported: true,
              url: status.url ?? settings.url,
              name: status.name ?? settings.name,
              agentId: status.agentId,
              channels: status.channels,
              connected: status.connected,
            );
          } on Object {
            // The plugin never started (opted out, or the connect failed):
            // report the resolved config without a live connection.
            return DapHubSnapshot(
              supported: true,
              url: settings.url,
              name: settings.name,
              channels: const [],
              connected: false,
            );
          }
        },
        onDapHubConfigChanged: ({url, name}) => persistDapConfig(
          url: url,
          name: name,
          file: defaultDapConfigFile(),
        ),
        onModelChanged: (_) async {
          await persistConfig();
          await persistFolderModelState();
        },
        // `/provider` switches: redact an explicitly passed session token so
        // it cannot leak into tool results or session files, then persist the
        // new provider/model/baseUrl triple (never the key itself).
        onProviderChanged: (kind, key) async {
          if (key.isNotEmpty) {
            redactor.register('/provider token', key);
            redactionPipeline?.registerSecret(key);
            // A keyless startup never attached the redactor; a runtime token
            // still gets masked from here on.
            if (!redactorAttached) {
              attachSecretRedactor(cli.agent, redactor);
              redactorAttached = true;
            }
          }
          await persistConfig();
          await persistFolderModelState();
        },
        // `/key set` stored a secret: mask it from here on (same lazy attach).
        onSecretStored: (name, value) {
          redactor.register(name, value);
          redactionPipeline?.registerSecret(value);
          if (!redactorAttached && !redactor.isEmpty) {
            attachSecretRedactor(cli.agent, redactor);
            redactorAttached = true;
          }
        },
        // `request_secret` tool granted a secret: same redactor lazy attach.
        onSecretGranted: (name, value) {
          redactor.register(name, value);
          redactionPipeline?.registerSecret(value);
          if (!redactorAttached && !redactor.isEmpty) {
            attachSecretRedactor(cli.agent, redactor);
            redactorAttached = true;
          }
        },
        onModeChanged: (_) async => persistConfig(),
        onApprovalChanged: () async => persistConfig(),
        // gh-1572 rework: the settings-hub flows write ~/.fah/config.yaml
        // directly (surgical validated-yaml upserts, drop-key edits).
        // Re-sync the boot snapshot after every sanctioned write so the
        // next persistConfig renders the freshest on-disk truth instead
        // of re-rendering the stale boot values over the flow's write.
        // A reload failure (unparseable file) keeps the previous
        // snapshot — the next save refuses loudly through its own
        // merge-step parse, same as before this hook existed.
        onUserConfigFileChanged: () async {
          try {
            saved = loadCliConfig(home);
          } on ConfigException {
            // Keep the previous snapshot (see above).
          }
        },
        // Global `tools:` toggles (`/tools <id> global`): the CLI owns the
        // live scope; persistConfig writes it back (see below).
        onToolsConfigChanged: () async => persistConfig(),
        // Third-party skills consent (`skills:` config section): the startup
        // dialog and `/skills access` set it; shell `!`cmd`` injections in
        // skill bodies follow `disableShellExecution`.
        skillsAccess: saved.skillsAccess,
        skillsDisableShellExecution: saved.skillsDisableShellExecution,
        skillsLiveRediscovery: saved.skillsLiveRediscovery,
        // Global per-skill toggles (`skills:` config section, issue #1151):
        // the CLI owns the live view; persistConfig writes it back.
        skillToggles: saved.skillToggles,
        onSkillsAccessChanged: (access) async {
          skillsAccess = access;
          await persistConfig();
        },
        onSkillTogglesChanged: () async => persistConfig(),
        // Shift+Enter in the TUI: HID polling when the startup gate allows
        // it (issue #355) — null over SSH, under FA_TUI_SHIFT_HID=0, after
        // a probe timeout, and on non-macOS hosts.
        isShiftPressed: hidShiftPressed,
        // Mouse capture is ON by default (wheel scrolls the session view —
        // in the alternate screen the terminal has no native scrollback, so
        // without capture two-finger scroll does nothing). FA_TUI_MOUSE=0
        // opts out for always-on native select-to-copy.
        tuiMouseCapture: _envNotFalsy('FA_TUI_MOUSE'),
        // DEC 2026 synchronized output: auto-detect by default; FA_TUI_SYNC
        // forces it on (terminals without DECRQM answers) or off (fallback).
        tuiSyncOutput: _envTristate('FA_TUI_SYNC'),
        // The omp band composer (#806): on unless `tui.classic: true` pins
        // the legacy chrome byte-identically.
        tuiClassic: saved.tuiClassic,
        // gh-1636: the compaction-report detail opt-in (default false —
        // auto-folds print the one-line marker).
        showCompactionDetails: saved.tuiShowCompactionDetails,
        statusLine: saved.statusLine,
        agentLoadMode: saved.agentLoadMode,
        // `/update` (issue #1377): the engine lives in bin/self_manage.dart
        // and lib stays dart:io-free, so the command calls back into this
        // closure — check, apply, spawn the successor, exit(0) on success;
        // print + stay alive on any failure. The LIVE session id rides
        // into the successor argv (appended only when the argv itself does
        // not carry one), so the conversation survives the restart.
        updateCommand: (sessionId) => _runSlashUpdate(
          currentVersion: packageVersion,
          launchArgs: successorArgs(args, sessionId),
          writeln: io.writeln,
        ),
        // The settings-hub row reads the live policy (slice B): seed it from
        // the loaded `auto_update:` section.
        autoUpdate: saved.autoUpdate,
      ),
      io: io,
    );
  } on ConfigException catch (error) {
    _fail(error.message);
  }
  if (redactorAttached) attachSecretRedactor(cli.agent, redactor);

  // Issue #823: boot builds the queue runtime before the CLI (and its
  // quota service) exist — rebind once so depletion hints steer the
  // resolver from the first turn. No-op without a configured queue.
  await cli.attachProviderQueueQuotaFeed();

  persistConfig = () async {
    await saveCliConfig(
      home,
      // gh-1572: [saved] is the BASE — every parsed section rides along
      // (copyWith), so a save can never reset a field the boot did not
      // mention (the old fresh-`CliConfig` construction silently dropped
      // spills/subagents/jobs/headless/agent/quota/tui/trajectory/waiting
      // on every boot). Only the session-live overlays are applied on
      // top; saveCliConfig's disk-preservation backstop additionally
      // re-attaches any top-level block the emitter omits. The rework's
      // onUserConfigFileChanged hook keeps [saved] fresh against the
      // sanctioned mid-session writes (settings-hub upserts and key
      // drops), so the base never re-renders over a newer edit.
      saved.copyWith(
        // The provider/model triple is per-folder now (folder_model_state):
        // keep the LOADED seed in the global config so a `/model` or
        // `/provider` switch in one workspace never leaks into the others
        // across restarts — the switch persists through the folder's state
        // file instead, and explicit --model/--provider/--base-url still
        // win per launch. copyWith keeps [saved]'s triple unless the live
        // resolver/registry replaced it below.
        mode: cli.currentMode.name,
        approvalMode: cli.approval.mode.label,
        allowedTools: cli.approval.alwaysAllowedTools,
        // Roles: the live resolver's config (a `/model` switch re-pins the
        // default chain, the settings-hub agent-models flow pins the
        // smol/subagent chains — possibly creating the resolver on demand).
        modelRoles: cli.config.modelRolesResolver?.config ?? saved.modelRoles,
        // Saved custom providers (the live registry the CLI mutates).
        customProviders:
            cli.config.customProviders?.entries ?? saved.customProviders,
        // Models config (the live instance `/models set`/`remove` mutates).
        models: cli.config.modelsConfig ?? saved.models,
        // MCP servers (the live config — re-read on `/mcp reload`).
        mcp: cli.config.mcpConfig?.config ?? saved.mcp,
        // Third-party skills consent (mutable via the startup dialog and
        // `/skills access`); shell-execution policy is static per session.
        skillsAccess: skillsAccess,
        // The live global `skills:` toggles (read from the loaded config,
        // updated by `/skills <name> global`); null before the first
        // resolution, in which case the loaded section is kept as-is.
        skillToggles: cli.globalSkillToggles ?? saved.skillToggles,
        // The saved cube default (the live value the Cube sandbox flow
        // rewrites; `saved.cube` keeps the section when nothing changed).
        cube: cli.config.cubeSettings ?? saved.cube,
        // The live global `tools:` scope (read at boot, updated by
        // `/tools <id> global`); null until the first availability
        // rebuild, in which case the loaded section is kept as-is
        // (project/runtime scopes stay live and are never persisted).
        tools: cli.globalTools ?? saved.tools,
        // `compaction:` rides along from [saved] — the LOADED global
        // value, never the settings-hub's live override
        // (AgentCliConfig.liveCompactionEngine) or a project-scope pick,
        // so a session/project selection cannot leak into the global
        // file. The strict section only ever holds `engine` +
        // `judgeBudgetSeconds`, so the typed render is value-faithful;
        // the global/project flows write their yaml through the targeted
        // upsert themselves and the session scope persists nothing.
      ),
    );
  };

  try {
    await persistConfig();
  } on ConfigException catch (error) {
    // Issue #221 E3: an unparseable config.yaml makes the save refuse
    // loudly instead of clobbering the file with defaults. Keep running
    // with the in-memory config; the user's file stays untouched.
    stderr.writeln('warning: config not saved: $error');
  }

  Future<void> resetTerminalForShell() async {
    if (!stdin.hasTerminal) return;
    stdout.write('\x1b[?1000l\x1b[?1002l\x1b[?1003l\x1b[?1006l');
    stdout.write('\x1b[?1004l\x1b[?2004l');
    stdout.write('\x1b[?25h\x1b[?1049l');
    await stdout.flush();
    // Drain any pending terminal query/mouse responses so they don't echo
    // as garbage at the shell prompt.
    try {
      final drain = stdin.listen((_) {});
      await Future<void>.delayed(const Duration(milliseconds: 150));
      await drain.cancel();
    } on Object {
      // Nothing to drain.
    }
  }

  // Double-press Ctrl+C exit, interactive arm (issue #830): SIGINT-parity
  // teardown the TUI's ctrl+c press 2 also triggers via
  // [AgentCli.onCtrlCExitRequest] — abort-if-running bounded, session
  // resume hint, exit 130. The exit code is guaranteed: teardown steps
  // may not throw the caller into an unhandled-error death, so the whole
  // body runs under finally (the old single-press path's safety net).
  Future<void> exitInteractive130() async {
    try {
      terminalIo.resetRawMode();
      stdout.writeln();
      // Restore terminal modes (mouse tracking off, alt-screen exit,
      // cursor show) BEFORE exit(130) — otherwise the shell prompt
      // inherits mouse reporting and wheel scrolls print escapes.
      await resetTerminalForShell();
      if (cli.isBusy) {
        terminalIo.fireInterrupt();
        await cli.waitForIdle();
      }
      await cli.deleteSessionIfEmpty();
      // Real stdout, not io: the TUI is being torn down by this very
      // exit — an io-routed line would land in a dead transcript. A
      // session with nothing persisted prints the honest no-op line —
      // "resume this session with ..." would point at a deleted file.
      final hint = await cli.sessionResumeHint();
      stdout.writeln(hint ?? kNothingToResumeHint);
      // gh-1455: drain through the shared chain — a bare flush here races
      // the in-flight per-line flushes and crashes the exit path.
      await drainStdoutLines();
    } finally {
      exit(130);
    }
  }

  cli.onCtrlCExitRequest = () => unawaited(exitInteractive130());

  final sigintSub = ProcessSignal.sigint.watch().listen((_) {
    final wasBusy = cli.isBusy;
    switch (cli.sigintPolicy.press(
      headless: headlessPrompt != null || wireServe.wireServe,
    )) {
      case SigintAction.interruptAndStay:
        // Press 1 (issue #830): abort the in-flight run (bounded) and
        // STAY ALIVE — the next press inside the window exits. The TUI
        // gets the footer hint + idle-composer clear via the model; line
        // mode prints a dim stderr line.
        if (wasBusy) terminalIo.fireInterrupt();
        final tui = cli.tuiController;
        if (tui != null) {
          tui.armInterruptHint();
        } else {
          stderr.writeln(
            dimCtrlCExitHint(supportsAnsiEscapes: stdout.supportsAnsiEscapes),
          );
        }
      case SigintAction.exitInteractive:
        unawaited(exitInteractive130());
      case SigintAction.exitHeadless:
        // Headless graceful abort (issue #155): fire the interrupt, then
        // let the RUN settle — [AgentCli.waitForIdle] tracks the REPL's
        // settle future, which headless never starts, so the run future
        // itself is the honest wait: abort lands, the partial transcript
        // persists, the HEP writer emits `cancelled`, THEN exit 130.
        _gracefulHeadlessExit(terminalIo.fireInterrupt);
    }
  });
  // Backend supervisors send SIGTERM (issue #155): route it through the
  // same graceful abort as SIGINT — partial persist + `cancelled` frame +
  // exit 130 — instead of dying mid-write. A second SIGTERM escalates
  // (graceful → forced), the usual supervisor contract. [stdout.flush]
  // matters: exit() drops the async write buffer, taking the just-written
  // `cancelled` frame with it. gh-1763: the abort names SIGTERM (never
  // masquerades as a user Ctrl+C).
  if (headlessPrompt != null) {
    ProcessSignal.sigterm.watch().listen((_) {
      if (_sigtermSeen) exit(143);
      _sigtermSeen = true;
      _gracefulHeadlessExit(terminalIo.fireInterrupt, signal: 'SIGTERM');
    });
  }

  // `fa wire-serve` (issue #1103): headless Agent Wire Protocol v1
  // server. SIGINT/SIGTERM: both route through _gracefulHeadlessExit,
  // whose fireInterrupt aborts any in-flight run and whose
  // _wireServeSettle call ends the transport — runWireServe's finally
  // persists, and this branch's `exit(code)` continuation (registered
  // before _gracefulHeadlessExit's) wins the race: a graceful server
  // shutdown is a success, exit 0 (143 on a second SIGTERM, the usual
  // supervisor escalation).
  if (wireServe.wireServe) {
    var sigtermSeen = false;
    final sigtermSub = ProcessSignal.sigterm.watch().listen((_) {
      if (sigtermSeen) exit(143);
      sigtermSeen = true;
      _gracefulHeadlessExit(terminalIo.fireInterrupt, signal: 'SIGTERM');
    });
    final int code;
    try {
      code = await (_headlessRun = _runWireServeHost(
        cli: cli,
        wireServe: wireServe,
        terminalIo: terminalIo,
      ));
    } finally {
      await sigtermSub.cancel();
      await sigintSub.cancel();
      await drainStdoutLines();
      logTeeFile?.closeSync();
    }
    exit(code);
  }

  if (headlessPrompt != null) {
    _headlessRun = cli.runHeadless(
      attachReferences.isEmpty
          ? headlessPrompt
          // Non-image --attach files pass through as path references
          // appended to the prompt (issue #196).
          : '$headlessPrompt\n\n${attachReferences.join('\n\n')}',
      images: attachedImages,
      hep: hep,
      streamJson: streamJson,
      waitForJobs: effective.waitForJobs,
    );
    final int code;
    try {
      code = (await _headlessRun)!;
    } finally {
      await sigintSub.cancel();
      await drainStdoutLines();
      logTeeFile?.closeSync();
    }
    exit(code);
  }

  try {
    await cli.run();
  } finally {
    await sigintSub.cancel();
    logTeeFile?.closeSync();
  }

  // dart_tui's shutdown writes the reset sequences (?25h ?1049l ?1002l etc.)
  // and flushes stdout, but on some terminals the mouse-tracking disable
  // (?1002l ?1006l) arrives too late or is lost. Write them again here with
  await resetTerminalForShell();
  exit(0);
}

/// The `/update` slash-command body (issue #1377): the same verified
/// engine path as the boot hook and `fa update` — check, download+verify,
/// swap, spawn the successor with the ORIGINAL argv (the session resume
/// flag is already in it), then exit(0) to hand it the terminal. Any
/// failure prints one line and stays alive on the current version;
/// `unsupportedPlatform` is silent here — the engine already printed the
/// restart prompt after the swap.
Future<void> _runSlashUpdate({
  required String currentVersion,
  required List<String> launchArgs,
  required void Function(String line) writeln,
}) async {
  final outcome = await applyUpdate(
    currentVersion: currentVersion,
    launchArgs: launchArgs,
  );
  switch (outcome) {
    case ApplyUpdateOutcome.applied:
      exit(0);
    case ApplyUpdateOutcome.upToDate:
      writeln('already up to date (v$currentVersion)');
    case ApplyUpdateOutcome.unsupportedPlatform:
      break;
    case ApplyUpdateOutcome.refusedDevRun:
      writeln('update unavailable for source runs');
    case _:
      writeln('update failed (${outcome.name}) — staying on v$currentVersion');
  }
}

part of 'fah.dart';

const _fallbackVersion = '0.1.0';

/// Reads the package version with four fallbacks so compiled binaries stay
/// accurate: `-DFA_VERSION=` baked at compile time (legacy AOT builds), then
/// a `version.txt` file alongside the `dart build cli` bundle, then the
/// `pubspec.yaml` next to the executable (source runs), then the constant.
String _packageVersion() {
  const fromEnv = String.fromEnvironment('FA_VERSION');
  if (fromEnv.isNotEmpty) return fromEnv;
  try {
    // Platform.resolvedExecutable always returns the full canonical path,
    // even when the binary was invoked via a bare name or relative path.
    // Platform.script may return a relative path on some platforms, which
    // makes exeDir = cwd instead of the binary's real directory.
    final exePath = Platform.resolvedExecutable;
    final exeDir = File(exePath).parent;
    final bundleRoot = exeDir.parent;
    // Try bundle/version.txt first (dart build cli layout).
    final versionFile = File('${bundleRoot.path}/version.txt');
    if (versionFile.existsSync()) {
      final v = versionFile.readAsStringSync().trim();
      if (v.isNotEmpty) return v;
    }
    // Try <exe_dir>/version.txt (installer layout: version.txt next to fa).
    final dirVersionFile = File('${exeDir.path}/version.txt');
    if (dirVersionFile.existsSync()) {
      final v = dirVersionFile.readAsStringSync().trim();
      if (v.isNotEmpty) return v;
    }
    // Source run: pubspec.yaml sits two levels up from bin/.
    final pubspec = File('${bundleRoot.path}/pubspec.yaml');
    final doc = yaml.loadYaml(pubspec.readAsStringSync()) as Map;
    final value = doc['version'];
    if (value is String && value.isNotEmpty) return value;
  } on Object {
    // Fall back to the compile-time constant when nothing is available.
  }
  return _fallbackVersion;
}

Never _fail(String message) {
  stderr.writeln('fa: $message');
  stderr.writeln('Run with --help for usage.');
  exit(64);
}

Never _exitWithUsage(String version) {
  stdout.write(cliHelpText(version));
  exit(0);
}

/// Set once the first SIGTERM arrived in a headless run (issue #155): a
/// second one escalates from graceful to forced.
var _sigtermSeen = false;

/// The in-flight headless run, awaited by the SIGINT/SIGTERM graceful
/// exits (issue #155). Set before the signals can matter, read only from
/// the exit paths.
Future<int>? _headlessRun;

/// wire-serve (issue #1103): ends the transport (completing the serve
/// future) so a signal-driven exit tears down GRACEFULLY — runWireServe's
/// finally aborts any in-flight run, persists, and the process exits.
/// Null outside wire-serve mode.
void Function()? _wireServeSettle;

/// Graceful headless abort shared by SIGINT and SIGTERM (issue #155):
/// abort the run, wait for it to settle (bounded — a wedged provider
/// cannot hold the exit), flush the HEP stream, exit 130.
///
/// gh-1763 AC3: the abort names its signal on stderr — a `SIGTERM` that
/// reached fa from a child process (a broad `pkill` inside a bash tool
/// call) must never read as a user Ctrl+C in the post-mortem log. The
/// exit code stays 130 (the pinned supervisor contract — a second SIGTERM
/// escalates to 143 in the caller).
void _gracefulHeadlessExit(
  void Function() fireInterrupt, {
  String signal = 'SIGINT',
}) {
  if (signal != 'SIGINT') {
    stderr.writeln(
      'fa: $signal received — aborting headless run gracefully '
      '(exit 130; a second $signal forces exit 143)',
    );
  }
  fireInterrupt();
  _wireServeSettle?.call();
  final run = _headlessRun;
  unawaited(
    Future(() async {
      if (run != null) {
        await run.timeout(const Duration(seconds: 10), onTimeout: () => 130);
      }
      // gh-1455: drain the serialized line chain instead of a bare flush —
      // a flush racing the in-flight per-line flushes is the exact
      // "StreamSink is bound to a stream" teardown crash.
      await drainStdoutLines();
    }).whenComplete(() => exit(130)),
  );
}

/// gh-1455: the ONE write+flush chain for headless stdout (HEP v1 and
/// stream-json lines). `stdout.flush()` marks the sink "bound" while in
/// flight, so the old unawaited per-line `stdout.flush()` racing the next
/// `writeln` — or the exit paths' own flush — threw the synchronous
/// `StateError("StreamSink is bound to a stream")` from an event-callback
/// frame: an uncaught zone error that crashed shutdown (crash.log) and let
/// the process linger until the runner's stall-kill. Every link is
/// guarded, so the chain itself can never reject; nothing escapes after
/// teardown.
Future<void> _stdoutLineChain = Future<void>.value();

/// Appends one line to [_stdoutLineChain] — write, then flush, both
/// guarded. Never throws.
void _enqueueStdoutLine(String line) {
  _stdoutLineChain = _stdoutLineChain.then((_) async {
    try {
      stdout.writeln(line);
      await stdout.flush();
    } on Object {
      // The sink is being torn down (or its stream already closed): a
      // crashed writer must not surface as an uncaught zone error.
    }
  });
}

/// Drains the line chain and flushes once more — the exit paths call this
/// instead of a bare `await stdout.flush()` so a final flush can never
/// overlap an in-flight chain link. Re-drains while stragglers enqueue
/// behind us (bounded), so the final flush is the true last sink
/// operation. Never throws.
Future<void> drainStdoutLines() async {
  for (var round = 0; round < 8; round++) {
    final chain = _stdoutLineChain;
    await chain;
    if (identical(chain, _stdoutLineChain)) break;
  }
  try {
    await stdout.flush();
  } on Object {
    // Same teardown guard as [_enqueueStdoutLine].
  }
}

/// One HEP JSONL line to stdout, flushed immediately (issue #155): a
/// supervisor tailing the pipe must never wait on a buffer.
void _writeHepLine(String line) {
  _enqueueStdoutLine(line);
}

/// One stream-json NDJSON line to stdout, flushed immediately (issue
/// #695): same live-pipe contract as HEP — `| jq` consumers tail the
/// stream line by line, and jsonEncode output is always single-line.
void _writeStreamJsonLine(String line) {
  _enqueueStdoutLine(line);
}

/// The mime reported when the magic-byte sniff misses — callers treat it
/// as "not an image" (issue #196 `--attach` passthrough).
const _unknownAttachMime = 'application/octet-stream';

/// Image type by magic bytes (issue #155 `--attach`): the file extension
/// is untrusted; the first bytes are. png/jpeg/gif/webp covered, else
/// [_unknownAttachMime].
String _sniffMime(Uint8List bytes) {
  bool startsWith(List<int> magic) {
    if (bytes.length < magic.length) return false;
    for (var i = 0; i < magic.length; i++) {
      if (bytes[i] != magic[i]) return false;
    }
    return true;
  }

  const png = [137, 80, 78, 71, 13, 10, 26, 10];
  if (startsWith(png)) return 'image/png';
  if (startsWith([0xFF, 0xD8, 0xFF])) return 'image/jpeg';
  if (startsWith([0x47, 0x49, 0x46, 0x38])) return 'image/gif';
  if (startsWith([0x52, 0x49, 0x46, 0x46]) &&
      bytes.length > 12 &&
      bytes[8] == 0x57 &&
      bytes[9] == 0x45 &&
      bytes[10] == 0x42 &&
      bytes[11] == 0x50) {
    return 'image/webp';
  }
  return _unknownAttachMime;
}

Never _exitWithVersion(String version, {String? output}) {
  if (output == 'json') {
    // Machine-readable for supervisors (issue #155): version + HEP
    // protocol version, one JSON object.
    stdout.writeln(jsonEncode({'version': version, 'hep': hepVersion}));
    exit(0);
  }
  stdout.writeln('fa $version');
  exit(0);
}

/// Writes an uncaught error to `~/.fah/crash.log` and stderr, then exits
/// non-zero. This is the last-resort handler so users can report what
/// happened instead of the CLI silently disappearing.
void _handleUncaughtError(Object error, StackTrace stackTrace) {
  final message = 'fa crashed: $error';
  stderr.writeln(message);
  if (error is SessionException ||
      message.contains('Failed to create session directory')) {
    stderr.writeln(
      '\nTip: If this is a permission issue with session storage, you can fix it by running:\n'
      '  sudo chown -R \$(whoami) ~/Library/"Group Containers"/group.dev.fa1.shared\n'
      '  chmod -R u+rwx ~/Library/"Group Containers"/group.dev.fa1.shared\n'
      'Or start fa with a custom session storage path:\n'
      '  fa --session-root ~/.fah/sessions\n',
    );
  }
  try {
    final home =
        Platform.environment['HOME'] ?? Platform.environment['USERPROFILE'];
    if (home != null && home.isNotEmpty) {
      final dir = Directory('$home/.fah');
      dir.createSync(recursive: true);
      final log = File('${dir.path}/crash.log');
      final timestamp = DateTime.now().toUtc().toIso8601String();
      final version = _packageVersion();
      final buffer = StringBuffer()
        ..writeln('timestamp: $timestamp')
        ..writeln('version: $version')
        ..writeln('type: ${error.runtimeType}')
        ..writeln('error: $error')
        ..writeln('stack:')
        ..writeln(stackTrace);
      log.writeAsStringSync('$buffer\n', mode: FileMode.append);
      stderr.writeln('details appended to ${log.path}');
    }
  } on Object catch (e) {
    stderr.writeln('could not write crash log: $e');
  }
  stderr.writeln('Run with --help for usage.');
  exit(1);
}

